from questions._util import q

QUESTIONS = [
    q("srv-nginx", "medium", "Nginx is the public listener and the app is on 127.0.0.1:8080. What belongs in the server block?", "proxy_pass to the app, plus forwarded headers.", "upstream with the app, plus a root directive.", "return 301 to the app's address and port.", "fastcgi_pass to the app's address and port.", "Nginx terminates the public connection and proxies. Headers tell the app the scheme and client address. A redirect would send clients to a loopback address, and fastcgi_pass speaks a different protocol."),
    q("srv-nginx", "medium", "What does nginx -t buy you before a reload?", "It validates the config before anything changes.", "It reloads only the workers whose config changed.", "It starts a test worker beside the old ones.", "It rolls back to the last good config if needed.", "Test, then reload. A reload that fails to parse keeps the old workers, but testing first tells you why before traffic is at stake."),
    q("srv-nginx", "hard", "The upstream is healthy and Nginx returns 413. What is the knob?", "client_max_body_size", "large_client_header_buffers", "proxy_buffer_size", "client_body_buffer_size", "413 is a request body larger than Nginx will accept. Header buffers give 400 or 414, and buffer sizes affect memory, not the limit. Raise it on purpose for the upload endpoint."),
    q("srv-nginx", "easy", "What is a worker process in Nginx?", "The process that handles client connections.", "The process that reads and validates config.", "A thread spawned for each incoming request.", "The process that writes the access log.", "The master reads config and manages workers. Workers handle connections with an event loop, so you scale them with CPU, not requests."),
    q("srv-apache", "medium", "You inherited an Apache server and the wrong vhost answers. What selects the vhost?", "ServerName or ServerAlias matching the Host header.", "The DocumentRoot that contains the requested path.", "The order of Include lines in apache2.conf.", "The vhost whose Listen directive matches the port.", "After the address and port match, name-based hosting picks by ServerName or ServerAlias. The first vhost for that address is only the default for unmatched names."),
    q("srv-apache", "easy", "Apache and Nginx are both reasonable choices for which job?", "Static files and reverse proxying.", "Running the application's code.", "Load balancing at L4 for UDP.", "Issuing TLS certificates via ACME.", "They are HTTP servers and proxies. The rest of the platform does not care which one, as long as the config is the one you tested."),
    q("srv-apache", "medium", "A .htaccess file changed nothing. What is a common reason?", "AllowOverride None for that directory.", "The file is not owned by the Apache user.", "Apache caches it until a graceful reload.", "mod_rewrite is required for any .htaccess.", "With AllowOverride None, Apache never reads .htaccess. It is re-read per request otherwise. That setting is also how you stop a web root changing auth rules."),
    q("srv-apache", "hard", "You are choosing between Nginx and Apache for a high-connection proxy. What is the real decision?", "Which one your team can configure and debug safely.", "Which one supports HTTP/2 to the upstream servers.", "Which one has a lower memory footprint per worker.", "Which one can terminate TLS without a module.", "Both can proxy at high connection counts. An unfamiliar rewrite language is an outage. Operability beats the benchmark you are not going to run."),
    q("srv-caddy", "medium", "What is Caddy's selling point on a small edge host?", "Automatic certificates with almost no config.", "Built-in load balancing across data centers.", "A web UI for editing proxy rules live.", "Native support for running PHP in-process.", "Automatic HTTPS is the feature. You still have to point DNS at the host and let it answer the ACME challenge."),
    q("srv-caddy", "easy", "A Caddy site block with reverse_proxy does the same job as:", "Nginx proxy_pass", "Nginx try_files", "Nginx rewrite", "Nginx alias", "Both are reverse proxies. The syntax changes, the role does not. try_files, rewrite and alias are about local files and URLs."),
    q("srv-caddy", "medium", "Automatic HTTPS failed. What do you check before blaming the proxy?", "DNS points here, and 80 or 443 is reachable.", "The site block lists a tls directive with email.", "The certificate store directory is world-writable.", "The host's clock is set to the CA's time zone.", "ACME needs a public name that resolves to this host and a reachable challenge port. An internal-only name needs an internal CA."),
    q("srv-caddy", "hard", "Why would you still put Caddy behind a cloud load balancer?", "Stable public address and health checks.", "Caddy cannot listen on privileged ports.", "Caddy cannot renew certificates on its own.", "The balancer is needed for HTTP/2 support.", "The balancer is the stable address and health check. Caddy is the HTTP config on the instance. Know which hop terminates TLS so you do not decrypt twice by accident."),
    q("srv-envoy", "medium", "In a service mesh, what is Envoy's usual job next to an app?", "The sidecar handling its traffic, mTLS and metrics.", "The control plane pushing config to other proxies.", "The CNI plugin wiring the pod's network.", "The admission webhook injecting the mesh labels.", "The app's traffic is redirected through the sidecar, and the sidecar talks to the rest of the mesh. istiod or similar is the control plane."),
    q("srv-envoy", "medium", "In Envoy, what do a listener, a route, and a cluster correspond to?", "Accepting, matching, and the upstream pool.", "Accepting, the upstream pool, and matching.", "Matching, accepting, and health checking.", "The port, the TLS context, and the filter chain.", "If the cluster has no healthy endpoints, the listener still accepts and then fails the request."),
    q("srv-envoy", "hard", "An eBPF program redirects connections into Envoy without the app knowing. What must the redirect avoid?", "Recapturing Envoy's own outbound connections.", "Redirecting connections to loopback addresses.", "Changing the source port of redirected flows.", "Redirecting UDP flows that Envoy cannot parse.", "Without a guard, Envoy's upstream connection is redirected back into Envoy in a loop. The usual guard is a mark or an identity so the proxy's own flows are skipped."),
    q("srv-envoy", "easy", "Envoy is not unique to one mesh. Where else is it used?", "Ingress controllers and API gateways.", "Container runtimes and image builders.", "Service discovery and DNS servers.", "Log shippers and metrics agents.", "Treat it as a programmable proxy you can run on its own. Contour, Emissary and Envoy Gateway use it. The control plane is what differs."),
    q("srv-cache", "medium", "When does a caching reverse proxy in front of an app help?", "Many clients fetch the same cacheable responses.", "Each client fetches its own personalized pages.", "The app is slow because of database write locks.", "Most requests are POSTs that change state.", "Cache what is safe to reuse, with freshness rules. Authenticated and personalized responses need explicit rules or you will leak one user to another."),
    q("srv-cache", "easy", "What does a CDN cache that your origin used to serve?", "Copies of cacheable responses near clients.", "Every response, including private ones.", "The origin's TLS session keys for reuse.", "Database query results for the origin.", "The origin still serves the first request and anything you mark private or uncacheable."),
    q("srv-cache", "medium", "You deployed a new asset and clients still see the old one. What is the lever?", "Hashed file names, or a purge of that URL.", "A restart of the origin to clear its cache.", "A shorter keepalive timeout on the proxy.", "A new ETag, which caches check every time.", "A new file at the same URL can sit in the cache until its TTL. Caches only revalidate the ETag once the copy is stale. Name assets with a hash, or purge."),
    q("srv-cache", "hard", "Why is caching a Set-Cookie response dangerous?", "The next client may receive the first one's session.", "The cookie expires before the cached copy does.", "Browsers reject cookies served from a cache.", "The cache strips the cookie and logs users out.", "Default rules should treat cookie and authorization responses as private."),
    q("ctr-images", "medium", "How do a tag and a digest on the same image differ?", "A tag can move. A digest names exact bytes.", "A digest can move. A tag names exact bytes.", "A tag names the config. A digest names a layer.", "A digest is per platform. A tag is per registry.", "Pin production by digest if you need the same bytes tomorrow. A multi-platform digest names an index that points at per-platform manifests."),
    q("ctr-images", "medium", "An image is a stack of layers plus config. What does that buy a rebuild?", "Unchanged layers are reused from cache.", "Changed layers are patched in place.", "Each layer is rebuilt in parallel.", "Only the final layer is ever pushed.", "Order the Dockerfile so the stable steps come first. The cache key is the instruction and its inputs, and layers are immutable once built."),
    q("ctr-images", "easy", "What is the writable layer of a running container?", "A thin layer that is removed with the container.", "A copy of the image that is saved on stop.", "A volume Docker creates for every container.", "The top image layer, opened in write mode.", "Put durable data in a volume. The container filesystem is not a disk you meant to keep, and image layers stay read-only."),
    q("ctr-images", "hard", "Two machines pull nginx:latest and run different code. How?", "The tag moved, or each got a different platform.", "The pull used cached layers from an older image.", "One machine pulled through a registry mirror.", "latest resolves differently per Docker version.", "latest is a pointer. A multi-platform tag also resolves per architecture. Record the digest you actually ran."),
    q("ctr-dockerfile", "medium", "Which instructions add filesystem layers that a changed input invalidates downstream?", "RUN, COPY, and ADD.", "FROM, ENV, and ARG.", "WORKDIR and USER.", "CMD and ENTRYPOINT.", "Keep volatile COPY commands late so the dependency install stays cached. The others change metadata, though ENV and ARG can still bust the cache for later steps."),
    q("ctr-dockerfile", "medium", "The container process is root and the Dockerfile never said USER. Why?", "The default user in an image is root.", "The base image sets USER root explicitly.", "Docker runs as root when no UID maps.", "USER only applies when set before FROM.", "Unless the base image or a USER line says otherwise, the process runs as UID 0. Add a user and set USER, or you shipped root."),
    q("ctr-dockerfile", "easy", "With an ENTRYPOINT and a CMD, what do arguments to docker run replace?", "CMD, and they are appended to ENTRYPOINT.", "ENTRYPOINT, and CMD is kept as arguments.", "Both, unless --entrypoint is also passed.", "Neither, they are added after CMD.", "Use ENTRYPOINT for the binary and CMD for default arguments if you want extra args to be natural."),
    q("ctr-dockerfile", "hard", "A shell-form RUN pipes to another command and the build passes even when the first command fails. Why?", "A pipeline's status is its last command.", "RUN ignores non-zero exits in shell form.", "BuildKit retries the step without the pipe.", "The first command runs in a subshell.", "RUN uses /bin/sh -c unless you use the exec form. Set SHELL with -o pipefail, or add it in that RUN."),
    q("ctr-multistage", "medium", "Why is a multi-stage build smaller and safer than shipping the compiler?", "Only the artifact reaches the final stage.", "Each stage is scanned before the next runs.", "Stages share one layer, so nothing repeats.", "The compiler is stripped from the binary.", "Build tools are an attack surface and a size cost. The toolchain and its vulnerabilities stay in the build stage."),
    q("ctr-multistage", "easy", "What does COPY --from=build /out/app /app do?", "Copies a file from the earlier stage named build.", "Copies a file from a running container named build.", "Copies a file from a local directory named build.", "Copies a file from an image tagged build on Hub.", "The build stage can be a fat SDK image. The last stage can be distroless or a tiny base. --from can name an image too, but build here is the stage."),
    q("ctr-multistage", "medium", "A Go binary built on Alpine fails in a scratch image with a dynamic linker error. What happened?", "It was linked dynamically, and scratch has no libc.", "It was built for a different CPU architecture.", "It needs CA certificates that scratch lacks.", "It was stripped, which breaks the ELF header.", "Build static with CGO_ENABLED=0, or use a runtime base that has the libraries you linked. Missing certs fail later, at TLS time."),
    q("ctr-multistage", "hard", "You copied a CA bundle into the runtime stage and HTTPS calls still fail. What is easy to forget?", "The app reads certs from a different path.", "CA bundles must be signed by the base image.", "The bundle needs update-ca-certificates run.", "The bundle must be in PEM order, root first.", "Know where that binary looks for trust. A file in the wrong directory is the same as a missing file."),
    q("ctr-registries", "medium", "A pull and a later deploy disagree about the image. You used a tag. What should the deploy record?", "The digest the tag resolved to.", "The image ID shown by docker images.", "The tag plus the time of the pull.", "The layer IDs of the image's top layer.", "The registry maps a tag to a digest at a moment in time. The digest is the identity. The local image ID is not what the registry serves."),
    q("ctr-registries", "medium", "A private registry pull works on your laptop and fails in the cluster with ImagePullBackOff. What does the cluster need?", "An imagePullSecret or node credentials.", "The registry's CA added to the pod spec.", "imagePullPolicy set to IfNotPresent.", "A NetworkPolicy allowing the registry.", "The cluster does not share your ~/.docker/config.json. Also check the tag exists there. Pulls are done by the node, so pod NetworkPolicy does not apply."),
    q("ctr-registries", "easy", "What is a registry, as opposed to a repository?", "The service. A repository is one image's tags.", "One image's tags. A repository is the service.", "The image index. A repository is its layers.", "A mirror. A repository is the upstream source.", "ghcr.io is a registry. ghcr.io/org/app is a repository with its tags."),
    q("ctr-registries", "hard", "You copied an image to an air-gapped registry and the signature does not verify. Why might that be?", "The signature artifact or signed manifest was not copied.", "Signatures are bound to the original registry hostname.", "The air-gapped registry recompressed the layers on push.", "Verification needs the transparency log online.", "Copy the signed manifest and its signature artifact, and re-check the digest on the far side. A retag can point at something else. Offline verification is possible with the right bundle."),
    q("ctr-volumes", "medium", "A container writes to /data and the writes are gone after a recreate. There was no volume. Why?", "The writable layer was removed with the old container.", "The writes stayed in the page cache and were not synced.", "/data is a tmpfs in images that declare VOLUME.", "Docker discards writes larger than the layer limit.", "A new container gets a new layer from the image. Mount a volume at /data if the bytes need to outlive the container."),
    q("ctr-volumes", "medium", "How do a bind mount and a named volume differ?", "A bind mount is a host path. A volume is Docker-managed.", "A bind mount is copied in. A volume is shared live.", "A volume is a host path. A bind mount is Docker-managed.", "A bind mount is read-only. A volume is read-write.", "Know which one you are debugging. A bind mount shows host permissions. A named volume lives under the Docker data root and is less obvious to back up."),
    q("ctr-volumes", "hard", "The app cannot write a bind-mounted directory that is 755 root:root. What is the mismatch?", "The container user is neither root nor the owner.", "Bind mounts are read-only unless :rw is given.", "The directory's SELinux label must be :z.", "The container must be privileged to write mounts.", "Align the UID or the mode. With SELinux you would see a denial even for root. Rootless and user namespaces also make host and container UIDs different numbers."),
    q("ctr-volumes", "easy", "What does a tmpfs mount give a container?", "A memory-backed filesystem gone on stop.", "A disk-backed scratch area kept on stop.", "A shared directory between two containers.", "A read-only copy of a host directory.", "Use it for secrets you do not want on disk, knowing a crash dump or a process listing can still leak them."),
    q("ctr-networks", "medium", "Two containers on the default bridge cannot reach each other by name, but on a user-defined bridge they can. Why?", "Only user-defined networks get name resolution.", "The default bridge blocks traffic between containers.", "The default bridge assigns no IPv4 addresses.", "Names resolve only when ports are published.", "Docker's embedded DNS serves user-defined networks. Put cooperating containers on a network you created."),
    q("ctr-networks", "medium", "A container cannot reach a service bound to 127.0.0.1 on the host. Why?", "Loopback in the container is its own namespace.", "Docker's NAT drops traffic to loopback addresses.", "The host firewall blocks the docker0 subnet.", "Services on loopback refuse non-root clients.", "127.0.0.1 inside the container is the container. Bind the service on an address the container can route to, or use host networking on purpose."),
    q("ctr-networks", "hard", "Which isolation does host network mode remove?", "The network namespace, so it shares host ports.", "The PID namespace, so it sees host processes.", "The mount namespace, so it sees host files.", "The user namespace, so it runs as host root.", "Use it deliberately. Port clashes and a missing network boundary are the cost. The other namespaces stay in place."),
    q("ctr-networks", "easy", "What is a veth pair's role in bridge networking?", "A virtual cable from the container to the bridge.", "A virtual NIC shared by all containers on the host.", "A tunnel from the container to the internet.", "A virtual switch port that tags VLAN traffic.", "One end is eth0 in the container namespace. The other is plugged into docker0 on the host."),
    q("ctr-ports", "medium", "What does -p 127.0.0.1:8080:80 do that a bare -p 8080:80 does not?", "Publishes only on the host's loopback address.", "Publishes on every interface except loopback.", "Restricts the container to loopback outbound.", "Publishes over IPv4 only, not over IPv6.", "Bind the address on purpose. The default publish listens on all addresses."),
    q("ctr-ports", "medium", "Several dev servers use the same container port and must run together. What avoids the clash?", "Map each to a different or random host port.", "Map all to one host port with SO_REUSEPORT.", "Put each on its own user-defined network.", "Use EXPOSE with a different port per image.", "Container ports do not clash. Host ports do. docker port or inspect tells you where each one landed."),
    q("ctr-ports", "hard", "You published a port on the internal IP only, and it is still reachable from the external network. Why?", "Docker's DNAT and FORWARD rules accept it first.", "Docker ignores the address in the -p option.", "docker-proxy listens on all addresses anyway.", "The external NIC has the internal IP aliased.", "Look at DOCKER-USER and the ingress interface, not only at the -p address."),
    q("ctr-ports", "easy", "What does EXPOSE in a Dockerfile do at runtime by itself?", "Nothing. It documents the port.", "Publishes the port on the host.", "Opens the port in the firewall.", "Binds the app to that port.", "Publish is a run or compose decision. -P publishes every exposed port, but EXPOSE alone does not."),
    q("ctr-compose", "medium", "What does depends_on without a health condition guarantee?", "The dependency container starts first.", "The dependency's port is accepting connections.", "The dependency restarts when the app does.", "The app waits for the dependency's healthcheck.", "Add a healthcheck and condition: service_healthy if the race matters. A database process existing is not a database accepting connections."),
    q("ctr-compose", "easy", "What file is the usual Compose definition?", "compose.yaml", "Dockerfile", "docker.json", "stack.toml", "The Dockerfile builds images. Compose runs the set. docker-compose.yml is the older name."),
    q("ctr-compose", "medium", "Why is a compose service name useful on the project network?", "Other services resolve it as a hostname.", "It sets the container's PID 1 process name.", "It becomes the default tag of the image.", "It is used as the volume's mount path.", "The name is the internal hostname. Do not hard-code container IPs."),
    q("ctr-compose", "hard", "You changed a build argument and compose up did not rebuild. What do you add?", "--build on compose up.", "--force-recreate on up.", "--renew-anon-volumes.", "--remove-orphans on up.", "Compose reuses an existing image when it thinks nothing changed. --force-recreate makes new containers from the same old image."),
    q("ctr-runtime", "medium", "How do dockerd, containerd, and runc divide the work?", "API, container supervisor, and OCI runtime.", "OCI runtime, API, and container supervisor.", "API, image builder, and network plugin.", "Registry client, API, and OCI runtime.", "A container is still a process. dockerd is the API you talk to, containerd supervises containers and shims, and runc creates the process."),
    q("ctr-runtime", "medium", "crictl and docker see different containers on a Kubernetes node. Why?", "The kubelet uses containerd via CRI, not dockerd.", "crictl lists only pods, while docker lists containers.", "docker hides containers started by root.", "crictl reads a cache that lags by minutes.", "Debug cluster containers with the CRI tool. docker ps can be empty on a containerd node."),
    q("ctr-runtime", "easy", "What is the OCI runtime spec about?", "Creating a container from config plus rootfs.", "Pushing and pulling images from registries.", "Building images from a Dockerfile.", "Wiring container network interfaces.", "runc implements that spec. The image spec and distribution spec cover images and registries, and CNI covers networking."),
    q("ctr-runtime", "hard", "When is Kata or another VM-based runtime chosen over runc?", "When you want a guest kernel as the boundary.", "When you want faster startup for short jobs.", "When you need direct access to host devices.", "When the workload needs host networking.", "Namespace escapes are host-kernel bugs. A separate kernel changes that trade, at a cost in startup time and density."),
    q("ctr-security", "medium", "The Docker socket is mode 660 root:docker. What did you grant the docker group?", "Full daemon control, which is host root.", "Read access to container logs and stats.", "The ability to run unprivileged containers.", "Container management without --privileged.", "There is no authorization plugin in a default install. The socket is the authorization."),
    q("ctr-security", "hard", "Which daemon port is the unsafe one to expose, and why?", "2375, plain TCP with no auth.", "2376, TLS but no client auth.", "2377, the swarm join token.", "2379, the etcd client port.", "An open 2375 is a remote root shell. 2376 is the TLS port with client certificates. Prefer SSH to the host over exposing the API."),
    q("ctr-security", "hard", "Why is docker run --privileged --pid=host --net=host -v /:/host a breakout?", "It drops isolation and mounts the host root.", "It runs the container's PID 1 as host init.", "It disables seccomp but keeps namespaces.", "It gives the container the host's IP only.", "The container can chroot into /host with full capabilities. Anyone who can pass those flags is an administrator."),
    q("ctr-security", "medium", "What does mounting /var/run/docker.sock into a container give it?", "Docker group power, a path to host root.", "Read-only access to the daemon's events.", "Access limited to its own container.", "Power filtered by the default seccomp.", "A CI helper that mounts the socket is a root shell that happens to live in a container. Seccomp filters syscalls, not API calls."),
    q("ctr-secrets", "medium", "A private module is fetched during docker build with a token in an ARG. What is wrong?", "ARG values leak into the image history and cache.", "ARG values are not available inside RUN steps.", "ARG values are only read from the .env file.", "ARG values expire after the first build stage.", "Use BuildKit --mount=type=secret so the credential never lands in a layer or in docker history."),
    q("ctr-secrets", "hard", "The secret mount is available in one RUN and gone in the next. Is that a bug?", "No. It is mounted for that one instruction.", "Yes. It should persist for the whole stage.", "Yes. It needs id= set to persist it.", "No. It is copied to /run/secrets later.", "The mount lasts for that instruction so the secret is never part of the filesystem you commit. Fetch what you need while it is there."),
    q("ctr-secrets", "easy", "Where should a runtime database password live?", "In a secret store, injected at start.", "In a Dockerfile ENV, set at build time.", "In an image label, read by the app.", "In a build ARG, passed by the pipeline.", "Images get copied. Treat them as public even when the registry is private."),
    q("ctr-secrets", "medium", "A multi-stage build copied a .netrc into the runtime stage by habit. What did you ship?", "The credentials, in the final image.", "Nothing, since dotfiles are skipped.", "Only a hash of the stored password.", "Nothing, if the file is in .dockerignore.", "The runtime stage is the image you run. Copy the artifact, not the home directory of the build. .dockerignore only filters the build context."),
    q("ctr-containerd", "medium", "On a containerd node, which CLI talks the same API the kubelet uses?", "crictl", "ctr", "nerdctl", "runc", "crictl uses the CRI socket. ctr and nerdctl talk containerd's own API and can show a different view. runc is below all of them."),
    q("ctr-containerd", "easy", "Why does nerdctl exist?", "A Docker-style CLI for containerd.", "A CRI debugging tool for kubelets.", "An OCI runtime that replaces runc.", "A build tool that replaces BuildKit.", "It is a client. containerd is still the daemon. crictl is the CRI tool."),
    q("ctr-containerd", "medium", "A pod is Running in kubectl and crictl ps shows no such container. What should you suspect?", "Wrong node, or a different runtime socket.", "The pod is Running but its image is pulling.", "crictl ps only lists stopped containers.", "The container is paused by the kubelet.", "The runtime is local to the node. Point the tool at the socket the kubelet uses, on the node that actually runs the pod."),
    q("ctr-containerd", "hard", "Why can ctr and crictl disagree about which containers exist?", "ctr defaults to another containerd namespace.", "crictl hides containers without a pod sandbox.", "ctr reads the image store, not running tasks.", "crictl talks to dockerd through a shim.", "containerd has its own namespaces, and the CRI plugin uses k8s.io. Pass -n k8s.io to ctr, or prefer crictl for cluster debugging."),
    q("ctr-rootless", "medium", "In rootless Docker, a container that thinks it is root shows up on the host as:", "The unprivileged user that runs the daemon.", "UID 0, with only some capabilities dropped.", "The nobody user, with no mapping at all.", "A random UID chosen per container start.", "User namespaces map container UID 0 to the user's UID. id inside says root, ps outside says the unprivileged account."),
    q("ctr-rootless", "hard", "What host package lets rootless mode allocate subordinate UIDs?", "uidmap", "fuse-overlayfs", "slirp4netns", "dbus-user-session", "uidmap provides newuidmap and newgidmap, which install the user namespace range. The others handle storage, networking and the user session."),
    q("ctr-rootless", "medium", "Rootless mode does not make a privileged container safe for strangers. What is still true?", "It can harm anything the daemon's user can.", "It can still load kernel modules on the host.", "It can still read every user's home directory.", "It can still bind ports below 1024 as root.", "It shrinks the blast radius from host root to that user. It is not a sandbox for untrusted code by itself."),
    q("ctr-rootless", "easy", "Why prefer rootless mode for a developer's Docker daemon?", "A socket compromise is not host root.", "Containers start faster without root.", "Images are smaller without root.", "Networking is faster without root.", "The daemon is the trust boundary. Do not run it as root if you do not need to. Rootless networking is usually slower, not faster."),
    q("ctr-debug", "medium", "A distroless container has no shell and you need to see a file. What is the Kubernetes-shaped answer?", "kubectl debug with an ephemeral container.", "kubectl exec with /bin/sh as the command.", "kubectl cp the file out of the container.", "kubectl attach to the container's stdin.", "exec and cp both need binaries in the image, and cp needs tar. A debug container brings the tools and shares the pod's namespaces."),
    q("ctr-debug", "medium", "You want a running process's view of its mounts without restarting it. What do you read?", "/proc/<pid>/mountinfo", "/proc/<pid>/maps", "/proc/<pid>/environ", "/proc/<pid>/fdinfo", "The live mount table is in proc. maps is memory mappings. The image history will not mention a volume added at run time."),
    q("ctr-debug", "hard", "A container resolves DNS but cannot open TCP to one address. Where do you split the fault?", "Routes and filters, tested from its netns.", "The resolver config, from its resolv.conf.", "The image, by pulling it again by digest.", "The DNS TTL, by flushing the host cache.", "DNS worked, so the name is not the problem. Use the container's netns: ip route, a connect to the IP, and a capture."),
    q("ctr-debug", "easy", "docker logs shows nothing and the app is quiet. What else carries its output?", "A log file the process writes inside the container.", "The Docker daemon's own log, in the systemd journal.", "The host's syslog, which Docker mirrors.", "The container's exit code, once it stops.", "stdout is a choice the process makes. Many servers log to a file instead, on a volume or in the writable layer."),
]
